   1: import { HashRouter, Navigate, Route, Routes } from 'react-router-dom'
   2: import { AppShell } from './components/AppShell'
   3: import { MemoryProvider } from './state/MemoryContext'
   4: import { HomePage } from './pages/HomePage'
   5: import { ChangesPage } from './pages/ChangesPage'
   6: import { MemoryPage } from './pages/MemoryPage'
   7: import { ChatPage } from './pages/ChatPage'
   8: import { AccessPage } from './pages/AccessPage'
   9: import { SettingsPage } from './pages/SettingsPage'
  10: 
  11: function App() {
  12:   return (
  13:     <HashRouter>
  14:       <MemoryProvider>
  15:         <Routes>
  16:           <Route element={<AppShell />}>
  17:             <Route path="/home" element={<HomePage />} />
  18:             <Route path="/changes" element={<ChangesPage />} />
  19:             <Route path="/memory/:lens" element={<MemoryPage />} />
  20:             <Route path="/chat" element={<ChatPage />} />
  21:             <Route path="/access" element={<AccessPage />} />
  22:             <Route path="/settings" element={<SettingsPage />} />
  23:             <Route path="*" element={<Navigate to="/home" replace />} />
  24:           </Route>
  25:         </Routes>
  26:       </MemoryProvider>
  27:     </HashRouter>
  28:   )
  29: }
  30: 
  31: export default App

--- src/data/mockMemoryRepository.ts ---
   1: import { demoWorkspace } from './demoWorkspace'
   2: import type {
   3:   AccessRule,
   4:   ChangeResolution,
   5:   CorrectionScope,
   6:   MemoryCategory,
   7:   MemoryChange,
   8:   MemoryCorrection,
   9:   MemoryItem,
  10:   MemoryRepository,
  11:   MemoryTension,
  12:   MemoryWorkspace,
  13:   TensionResolution,
  14: } from '../domain/memory'
  15: 
  16: const cloneWorkspace = () => structuredClone(demoWorkspace)
  17: 
  18: export class MockMemoryRepository implements MemoryRepository {
  19:   private workspace = cloneWorkspace()
  20: 
  21:   async loadWorkspace(): Promise<MemoryWorkspace> {
  22:     return structuredClone(this.workspace)
  23:   }
  24: 
  25:   async resolveChange(id: string, _action: ChangeResolution): Promise<MemoryChange> {
  26:     const change = this.workspace.changes.find((item) => item.id === id)
  27:     if (!change) throw new Error(`Unknown change: ${id}`)
  28:     change.status = 'resolved'
  29:     return structuredClone(change)
  30:   }
  31: 
  32:   async setPinned(id: string, pinned: boolean): Promise<MemoryItem> {
  33:     const memory = this.workspace.memories.find((item) => item.id === id)
  34:     if (!memory) throw new Error(`Unknown memory: ${id}`)
  35:     memory.pinned = pinned
  36:     return structuredClone(memory)
  37:   }
  38: 
  39:   async resolveTension(id: string, action: TensionResolution): Promise<MemoryTension> {
  40:     const tension = this.workspace.tensions.find((item) => item.id === id)
  41:     if (!tension) throw new Error(`Unknown tension: ${id}`)
  42:     tension.status = 'resolved'
  43:     tension.resolution = action
  44:     return structuredClone(tension)
  45:   }
  46: 
  47:   async applyCorrection(id: string, scope: CorrectionScope): Promise<MemoryCorrection> {
  48:     const correction = this.workspace.correction
  49:     if (correction.id !== id) throw new Error(`Unknown correction: ${id}`)
  50:     correction.scope = scope
  51:     correction.status = scope === 'ignore' ? 'ignored' : 'applied'
  52:     return structuredClone(correction)
  53:   }
  54: 
  55:   async updateAccess(appId: string, category: MemoryCategory, enabled: boolean): Promise<AccessRule> {
  56:     const rule = this.workspace.accessRules.find((item) => item.appId === appId && item.category === category)
  57:     if (!rule) throw new Error(`Unknown access rule: ${appId}/${category}`)
  58:     rule.enabled = enabled
  59:     return structuredClone(rule)
  60:   }
  61: 
  62:   async resetDemo(): Promise<MemoryWorkspace> {
  63:     this.workspace = cloneWorkspace()
  64:     return this.loadWorkspace()
  65:   }
  66: }

