--- src/state/MemoryContext.tsx ---
   1: // oxlint-disable react/only-export-components -- the typed hook is the provider's public boundary.
   2: import { createContext, useCallback, useContext, useEffect, useState, type ReactNode } from 'react'
   3: import { MockMemoryRepository } from '../data/mockMemoryRepository'
   4: import type { ChangeResolution, CorrectionScope, MemoryCategory, MemoryRepository, MemoryWorkspace, TensionResolution } from '../domain/memory'
   5: 
   6: interface MemoryContextValue {
   7:   workspace: MemoryWorkspace
   8:   repository: MemoryRepository
   9:   performanceMode: boolean
  10:   setPerformanceMode: (value: boolean) => void
  11:   refresh: () => Promise<void>
  12:   resolveChange: (id: string, action: ChangeResolution) => Promise<void>
  13:   setPinned: (id: string, pinned: boolean) => Promise<void>
  14:   resolveTension: (id: string, action: TensionResolution) => Promise<void>
  15:   applyCorrection: (id: string, scope: CorrectionScope) => Promise<void>
  16:   updateAccess: (appId: string, category: MemoryCategory, enabled: boolean) => Promise<void>
  17:   resetDemo: () => Promise<void>
  18:   toast: string | null
  19: }
  20: 
  21: const MemoryContext = createContext<MemoryContextValue | null>(null)
  22: 
  23: export function MemoryProvider({ children }: { children: ReactNode }) {
  24:   const [repository] = useState<MemoryRepository>(() => new MockMemoryRepository())
  25:   const [workspace, setWorkspace] = useState<MemoryWorkspace | null>(null)
  26:   const [performanceMode, setPerformanceMode] = useState(false)
  27:   const [error, setError] = useState<string | null>(null)
  28:   const [toast, setToast] = useState<string | null>(null)
  29: 
  30:   const refresh = useCallback(async () => {
  31:     try {
  32:       setError(null)
  33:       setWorkspace(await repository.loadWorkspace())
  34:     } catch {
  35:       setError('기억을 불러오지 못했습니다.')
  36:     }
  37:   }, [repository])
  38: 
  39:   useEffect(() => { void refresh() }, [refresh])
  40: 
  41:   const run = async (operation: () => Promise<unknown>, message?: string) => {
  42:     try {
  43:       await operation()
  44:       await refresh()
  45:       if (message) setToast(message)
  46:     } catch {
  47:       setToast('변경을 저장하지 못했습니다. 다시 시도해 주세요.')
  48:     }
  49:   }
  50: 
  51:   const actions = {
  52:     resolveChange: (id: string, action: ChangeResolution) => run(() => repository.resolveChange(id, action), '기억을 업데이트했습니다.'),
  53:     setPinned: (id: string, pinned: boolean) => run(() => repository.setPinned(id, pinned)),
  54:     resolveTension: (id: string, action: TensionResolution) => run(() => repository.resolveTension(id, action), action === 'conditional' ? '조건부 기억으로 분리했습니다.' : '선택한 기억만 남겼습니다.'),
  55:     applyCorrection: (id: string, scope: CorrectionScope) => run(() => repository.applyCorrection(id, scope), scope === 'global' ? '모든 대화에 반영했습니다.' : scope === 'conversation' ? '이 대화에만 반영했습니다.' : '수정 제안을 무시했습니다.'),
  56:     updateAccess: (appId: string, category: MemoryCategory, enabled: boolean) => run(() => repository.updateAccess(appId, category, enabled)),
  57:     resetDemo: () => run(() => repository.resetDemo(), '데모 데이터를 초기 상태로 되돌렸습니다.'),
  58:   }
  59: 
  60:   const value = workspace ? ({ workspace, repository, performanceMode, setPerformanceMode, refresh, toast, ...actions }) : null
  61: 
  62:   if (error) return <main><p>{error}</p><button onClick={() => void refresh()}>다시 시도</button></main>
  63:   if (!value) return <div aria-label="기억 불러오는 중" role="status" />
  64:   return <MemoryContext.Provider value={value}>{children}</MemoryContext.Provider>
  65: }
  66: 
  67: export function useMemory() {
  68:   const value = useContext(MemoryContext)
  69:   if (!value) throw new Error('useMemory must be used inside MemoryProvider')
  70:   return value
  71: }

