   5: .datePicker:hover { color: var(--text); }
   6: .datePicker:focus-visible { outline: 2px solid var(--paper); outline-offset: 4px; border-radius: 4px; }
   7: .heading { margin: 0; max-width: 820px; font: 400 38px/1.27 'Space Grotesk','Noto Sans KR'; letter-spacing: -.04em; }
   8: .description { max-width: 680px; margin: 12px 0 0; color: var(--text-soft); font-size: 14px; font-weight: 300; line-height: 1.75; }
   9: .topRow { display: flex; align-items: flex-end; justify-content: space-between; gap: 30px; }
  10: .tabs { display: flex; align-items: center; gap: 5px; padding: 4px; border: 1px solid var(--line-strong); border-radius: 12px; background: var(--surface-1); }
  11: .tabs a { padding: 10px 14px; border-radius: 8px; color: var(--text-soft); font: 500 12px/1 'Space Grotesk'; text-decoration: none; }
  12: .tabs a[aria-current='page'] { color: var(--ink); background: var(--paper); }
  13: .button, .buttonGhost, .textButton { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 42px; padding: 0 17px; border-radius: 11px; font-size: 13px; font-weight: 500; cursor: pointer; transition: 160ms var(--ease); }
  14: .button { border: 1px solid var(--paper); color: var(--ink); background: var(--paper); }
  15: .button:hover { background: white; }
  16: .buttonGhost { border: 1px solid var(--line-strong); color: var(--text-soft); background: transparent; }
  17: .buttonGhost:hover { color: var(--text); background: rgba(242,239,228,.06); }
  18: .textButton { border: 0; color: var(--text-dim); background: transparent; }
