--- src/components/AppShell.module.css ---
   1: .shell { display: grid; grid-template-columns: 224px minmax(0, 1fr); width: 100vw; height: 100vh; background: var(--bg); }
   2: .sidebar { display: flex; flex-direction: column; min-height: 0; padding: 24px 14px 16px; border-right: 1px solid var(--line); background: #0a0b0d; }
   3: .brand { display: flex; align-items: center; gap: 10px; padding: 0 10px; font: 500 15px/1 'Space Grotesk'; letter-spacing: -.02em; }
   4: .brandMark { display: grid; place-items: center; width: 28px; height: 28px; border: 1px solid var(--line-strong); border-radius: 50%; }
   5: .status { display: flex; align-items: center; gap: 7px; margin: 25px 10px 17px; color: var(--text-dim); font: 500 8px/1 'Space Grotesk'; letter-spacing: .14em; }
   6: .status b { margin-left: auto; color: var(--text-soft); font-size: 9px; }
   7: .liveDot { width: 5px; height: 5px; border-radius: 50%; background: var(--paper); box-shadow: 0 0 10px var(--paper); }
   8: .nav { display: flex; flex-direction: column; gap: 3px; }
   9: .navItem, .modeButton { position: relative; display: flex; align-items: center; gap: 11px; width: 100%; min-height: 48px; padding: 8px 10px; border: 0; border-radius: 9px; color: var(--text-dim); background: transparent; text-decoration: none; cursor: pointer; transition: background 180ms var(--ease), color 180ms var(--ease); }
  10: .navItem:hover, .modeButton:hover { color: var(--text-soft); background: rgba(242,239,228,.04); }
  11: .navItem.active { color: var(--text); background: rgba(242,239,228,.075); }
  12: .navItem.active::before { position: absolute; left: -14px; width: 2px; height: 22px; border-radius: 2px; background: var(--paper); content: ''; }
  13: .navItem span, .modeButton span { display: flex; flex: 1; flex-direction: column; gap: 4px; text-align: left; }
  14: .navItem strong, .modeButton strong { font: 500 12px/1 'Space Grotesk'; letter-spacing: .01em; }
  15: .navItem small, .modeButton small { color: var(--text-dim); font: 300 9px/1 'Noto Sans KR'; }
  16: .navItem em { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; color: var(--ink); background: var(--paper); font: 600 9px/1 'Space Grotesk'; font-style: normal; }
  17: .sidebarBottom { display: flex; flex-direction: column; gap: 3px; margin-top: auto; }
  18: .modeButton { border-top: 1px solid var(--line); border-radius: 0; }
  19: .profile { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 13px 10px 4px; border-top: 1px solid var(--line); color: var(--text-dim); }
  20: .profile > span { display: grid; place-items: center; width: 28px; height: 28px; flex: none; border-radius: 50%; color: var(--ink); background: var(--paper); font: 600 9px/1 'Space Grotesk'; }
  21: .profile div { display: flex; min-width: 0; flex: 1; flex-direction: column; gap: 4px; }
  22: .profile strong { color: var(--text-soft); font: 500 10px/1 'Space Grotesk'; }
  23: .profile small { overflow: hidden; font-size: 8px; text-overflow: ellipsis; white-space: nowrap; }
  24: .main { min-width: 0; min-height: 0; overflow: hidden; }
  25: .toast { position: fixed; z-index: 100; right: 28px; bottom: 24px; padding: 11px 15px; border: 1px solid var(--line-strong); border-radius: 10px; color: var(--ink); background: var(--paper); box-shadow: 0 18px 45px rgba(0,0,0,.38); font-size: 10px; animation: toastIn 220ms var(--ease); }
  26: @keyframes toastIn { from { opacity: 0; transform: translateY(8px); } }
  27: .performance :global(.visual-extra) { display: none !important; }
  28: .performance :global(.visual-blur) { filter: none !important; }

