--- src/index.css ---
   1: :root {
   2:   --bg: #08090b;
   3:   --surface-0: #0b0c0f;
   4:   --surface-1: #101216;
   5:   --surface-2: #15181d;
   6:   --surface-3: #1b1e24;
   7:   --line: rgba(242, 239, 228, 0.1);
   8:   --line-strong: rgba(242, 239, 228, 0.2);
   9:   --text: #f2efe4;
  10:   --text-soft: rgba(242, 239, 228, 0.68);
  11:   --text-dim: rgba(242, 239, 228, 0.4);
  12:   --paper: #f2efe4;
  13:   --ink: #0b0c0f;
  14:   --glass-surface: rgba(18, 20, 26, 0.58);
  15:   --glass-surface-strong: rgba(24, 27, 34, 0.72);
  16:   --glass-border: rgba(255, 255, 255, 0.14);
  17:   --glass-highlight: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  18:   --glass-shadow: 0 24px 64px rgba(0, 0, 0, 0.28);
  19:   --ease: cubic-bezier(0.23, 1, 0.32, 1);
  20:   color: var(--text);
  21:   background: var(--bg);
  22:   font-family: 'Noto Sans KR', system-ui, sans-serif;
  23:   font-synthesis: none;
  24:   text-rendering: optimizeLegibility;
  25:   -webkit-font-smoothing: antialiased;
  26: }
  27: 
  28: * { box-sizing: border-box; }
  29: html, body, #root { width: 100%; min-width: 1180px; min-height: 100%; margin: 0; }
  30: body { min-height: 100vh; overflow: hidden; background: var(--bg); }
  31: button, input { font: inherit; }
  32: button, a { -webkit-tap-highlight-color: transparent; }
